import itertools

def check_kawaii(sequence):
    N = len(sequence)

    # Find maximum element M
    M = max(sequence) if sequence else 0

    # Check conditions for k = 2 up to M
    for k in range(2, M + 1):

        # 1. Check if k appears
        if k in sequence:
            k_minus_1 = k - 1

            # 2. Check if k-1 appears
            if k_minus_1 not in sequence:
                return False

            # Find indices (1-based for clarity, or 0-based if consistent)
            # Using 0-based indices:

            # First occurrence of k-1
            try:
                i_first_k_minus_1 = sequence.index(k_minus_1)
            except ValueError:
                # Should not happen due to check above
                return False 

            # Last occurrence of k
            i_last_k = N - 1 - sequence[::-1].index(k)

            # 3. Check positional requirement
            if i_first_k_minus_1 >= i_last_k:
                return False

    return True

# Total sequences of length 4 using {1, 2, 3} is 3^4 = 81.
# We only care about those containing {1, 2, 3}.

S_target = {1, 2, 3}
count_S3 = 0

# Iterate over all 3^4 sequences
for seq in itertools.product([1, 2, 3], repeat=4):
    seq_tuple = tuple(seq)

    # Check if the sequence uses exactly {1, 2, 3}
    if set(seq) == S_target:
        if check_kawaii(seq):
            count_S3 += 1

print(f"Count for S={S_target}: {count_S3}")

# --- Verification for S={1, 2} ---
S_target_2 = {1, 2}
count_S2 = 0
for seq in itertools.product([1, 2], repeat=4):
    seq_tuple = tuple(seq)
    if set(seq) == S_target_2:
        if check_kawaii(seq):
            count_S2 += 1
print(f"Count for S={S_target_2}: {count_S2}")

# --- Verification for S={1, 2, 3, 4} ---
# Only the permutation (1, 2, 3, 4) should count (4! = 24)
S_target_4 = {1, 2, 3, 4}
count_S4 = 0
for seq in itertools.product([1, 2, 3, 4], repeat=4):
    seq_tuple = tuple(seq)
    if set(seq) == S_target_4:
        if check_kawaii(seq):
            count_S4 += 1
print(f"Count for S={S_target_4}: {count_S4}")

